// Resolution-independent art; the same shapes are used in the preview and game.
export function drawBaseball(c,x,y,r){c.save();c.translate(x,y);c.rotate(-.25);c.fillStyle='#fffdf6';c.strokeStyle='#d7ceba';c.lineWidth=r*.085;c.beginPath();c.arc(0,0,r,0,Math.PI*2);c.fill();c.stroke();c.strokeStyle='#df7278';c.lineWidth=r*.085;c.lineCap='round';for(const side of [-1,1]){c.beginPath();c.moveTo(side*r*.68,-r*.7);c.bezierCurveTo(side*r*.2,-r*.25,side*r*.2,r*.25,side*r*.68,r*.7);c.stroke();for(let i=-2;i<=2;i++){const yy=i*r*.23,xx=side*r*(.33+.35*(yy/r)**2);c.beginPath();c.moveTo(xx-r*.1,yy-r*.07);c.lineTo(xx+r*.1,yy+r*.04);c.stroke();}}c.restore();}
export function drawSnakeHead(c,x,y,r,direction='right',blink=false){c.save();c.translate(x,y);c.rotate(({right:0,down:Math.PI/2,left:Math.PI,up:-Math.PI/2})[direction]);c.fillStyle='#5276e7';c.beginPath();c.roundRect(-r,-r*.78,r*2.15,r*1.56,r*.7);c.fill();for(const side of [-1,1]){c.fillStyle='#5276e7';c.beginPath();c.arc(r*.05,side*r*.73,r*.43,0,Math.PI*2);c.fill();c.fillStyle='#fff';c.beginPath();c.ellipse(r*.09,side*r*.74,r*.33,blink?r*.08:r*.34,0,0,Math.PI*2);c.fill();c.fillStyle='#223b78';c.beginPath();c.ellipse(r*.21,side*r*.74,r*.14,blink?r*.025:r*.19,0,0,Math.PI*2);c.fill();if(!blink){c.fillStyle='#fff';c.beginPath();c.arc(r*.24,side*r*.74-r*.07,r*.04,0,Math.PI*2);c.fill();}}c.fillStyle='#2d4eae';for(const side of [-1,1]){c.beginPath();c.ellipse(r*.83,side*r*.19,r*.04,r*.065,0,0,Math.PI*2);c.fill();}c.strokeStyle='#2f52b3';c.lineWidth=r*.055;c.lineCap='round';c.beginPath();c.moveTo(r*.44,r*.42);c.quadraticCurveTo(r*.8,r*.53,r*1.02,r*.28);c.stroke();c.restore();}
export function drawSnakeScene(c,game,{width,height,progress=1,now=0}={}){const cell=Math.min(width,height)/20,padX=(width-cell*20)/2,padY=(height-cell*20)/2;c.clearRect(0,0,width,height);c.fillStyle='#eff5f3';c.fillRect(0,0,width,height);c.save();c.translate(padX,padY);c.fillStyle='#e3eeeb';for(let y=0;y<20;y++)for(let x=0;x<20;x++)if((x+y)%2===0)c.fillRect(x*cell,y*cell,cell,cell);
 if(game.food){const f=game.food,pulse=1+Math.sin(now/250)*.045;c.fillStyle='#253d5b0c';c.beginPath();c.ellipse((f.x+.5)*cell,(f.y+.82)*cell,cell*.35,cell*.11,0,0,Math.PI*2);c.fill();drawBaseball(c,(f.x+.5)*cell,(f.y+.5)*cell,cell*.4*pulse);}
 const points=game.body.map((p,i)=>{const old=game.previous[i]||game.previous.at(-1)||p;return{x:(old.x+(p.x-old.x)*progress+.5)*cell,y:(old.y+(p.y-old.y)*progress+.5)*cell};});
 c.strokeStyle='#5276e7';c.lineWidth=cell*.77;c.lineCap='round';c.lineJoin='round';c.beginPath();points.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.stroke();c.strokeStyle='#5276e7';c.lineWidth=cell*.62;c.stroke();const tail=points.at(-1);c.fillStyle='#5276e7';c.beginPath();c.arc(tail.x,tail.y,cell*.26,0,Math.PI*2);c.fill();drawSnakeHead(c,points[0].x,points[0].y,cell*.54,game.direction,now%3800>3650);c.restore();}
